  const now=ctx.currentTime,master=ctx.createGain();master.gain.value=this.volume;master.connect(ctx.destination);
  const presets={tap:{notes:[620],dur:.055,wave:'sine'},build:{notes:[175,262,392],dur:.34,wave:'triangle'},good:{notes:[523,659,784],dur:.42,wave:'sine'},bad:{notes:[210,165],dur:.3,wave:'triangle'},turn:{notes:[330,440,554],dur:.35,wave:'sine'},battle:{notes:[110,147,196],dur:.55,wave:'sawtooth'},event:{notes:[587,784,988],dur:.62,wave:'sine'},recruit:{notes:[220,330,440],dur:.4,wave:'square'},research:{notes:[523,698,880,1046],dur:.7,wave:'sine'},claim:{notes:[392,523,659,784],dur:.52,wave:'triangle'}};
