function seeded(x,y,seed=813){let v=Math.sin(x*127.1+y*311.7+seed*74.7)*43758.5453;return v-Math.floor(v)}
function terrainAt(q,r){let a=seeded(q,r,19),b=seeded(q+5,r-7,113);if((q===9&&r===7)||a<.24)return TERRAIN[0];if(a<.42)return TERRAIN[1];if(a<.60)return TERRAIN[2];if(a<.70)return TERRAIN[3];if(a<.78)return TERRAIN[4];if(a<.84)return TERRAIN[5];if(a<.92)return TERRAIN[6];return TERRAIN[7]}
function hexDist(a,b){let dq=a.q-b.q,dr=a.r-b.r;return (Math.abs(dq)+Math.abs(dr)+Math.abs(dq+dr))/2}
function tileId(q,r){return q+'_'+r}
function getTile(q,r){return WORLD.tiles.find(t=>t.q===q&&t.r===r)}
function makeWorld(){WORLD.tiles=[];for(let r=0;r<WORLD.rows;r++)for(let q=0;q<WORLD.cols;q++){let tr=terrainAt(q,r),resource=tr.resource;if((q===9&&r===7)|| (q===2&&r===2)||(q===16&&r===3)||(q===15&&r===12)){tr=TERRAIN[0];resource='food'}WORLD.tiles.push({id:tileId(q,r),q,r,terrain:tr.id,resource,owner:null,discovered:false,fort:0,capital:null,building:null})}
 const starts=[{id:'player',q:9,r:7},{id:'north',q:2,r:2},{id:'south',q:16,r:3},{id:'east',q:15,r:12}];
 for(const st of starts){for(const t of WORLD.tiles){if(hexDist(t,st)<=1){t.terrain='plain';t.resource='food';t.owner=st.id;t.discovered=st.id==='player'||hexDist(t,st)===0}if(hexDist(t,st)<=2&&st.id==='player')t.discovered=true}let c=getTile(st.q,st.r);if(c)c.capital=st.id}
 // Resource veins are deterministic and distributed across suitable land.
 for(const t of WORLD.tiles){if(!TERRAIN.find(x=>x.id===t.terrain)?.pass)continue;let r=seeded(t.q*3,t.r*7,71);if(t.terrain==='hill'&&r>.36)t.resource=r>.82?'gold':'stone';if(t.terrain==='mountain')t.resource=r>.62?'iron':'stone';if(t.terrain==='forest')t.resource='wood';if(t.terrain==='plain'||t.terrain==='tundra')t.resource='food';if(t.terrain==='desert')t.resource=r>.55?'gold':'food'}
}
function newState(realmId){let realm=realms[realmId]||realms.ashen;S={version:5,seed:813,realm:realmId,turn:1,level:1,xp:0,crown:0,population:680,stability:82,morale:74,resources:{gold:690,wood:510,stone:430,food:570,iron:135,knowledge:35,influence:12},army:{militia:12,swords:5,spears:5,archers:5,cavalry:1,knights:0,engineers:0},buildings:[],queue:[],research:[],relations:{north:0,south:-1,east:0},treaties:[],alliances:[],wars:[],factions:deep(FACTIONS),quests:{build:0,claim:0,wins:0,tech:0},completedQuests:[],claimed:[],eventLog:['نخستین پرچم دودمان بر فراز ارگ تاج‌شکسته برافراشته شد.'],settings:deep(settings),lastSaved:Date.now(),selected:null};
 makeWorld();let startBuildings=['keep','farm','sawmill','quarry','barracks','market'];let plots=[[9,7],[8,7],[10,7],[9,6],[9,8],[8,8]];startBuildings.forEach((type,i)=>{let t=getTile(plots[i][0],plots[i][1]);if(t){t.owner='player';t.discovered=true;t.building=type}S.buildings.push({id:i+1,type,level:1,tileId:t?t.id:null})});S.nextBuildingId=7;S.factions.forEach(f=>{for(const t of WORLD.tiles)if(t.owner===f.id)t.discovered=false;let c=getTile(f.base.q,f.base.r);if(c){c.discovered=false;c.capital=f.id}});
 // Restore player visibility after AI territories are hidden.
 for(const t of WORLD.tiles)if(t.owner==='player')t.discovered=true;for(const t of WORLD.tiles)if(hexDist(t,{q:9,r:7})<=2)t.discovered=true;
 S.resources[realm.resBonus]=Math.floor(S.resources[realm.resBonus]*1.15);if(realmId==='vale')S.morale=82;
 S.claimed=WORLD.tiles.filter(t=>t.owner==='player').map(t=>t.id);saveGame();return S}
function restoreWorld(snapshot){WORLD.tiles=snapshot.map(t=>({...t}));if(!WORLD.tiles.length)makeWorld()}
function initDust(){let box=$('introDust');for(let i=0;i<34;i++){let d=document.createElement('i');d.className='dust';d.style.left=(Math.random()*100)+'%';d.style.top=(Math.random()*110+10)+'%';d.style.animationDuration=(6+Math.random()*11)+'s';d.style.animationDelay=(-Math.random()*12)+'s';d.style.setProperty('--dx',(Math.random()*170-85)+'px');box.appendChild(d)}}
function startMusic(){if(!settings.music)return;music.volume=settings.volume;music.play().catch(()=>{})}
function showMenu(){ $('intro').classList.remove('active','playing');$('intro').style.display='none';$('menu').style.display='flex';$('menu').classList.remove('menu-reveal');requestAnimationFrame(()=>requestAnimationFrame(()=>$('menu').classList.add('menu-reveal')));$('game').style.display='none';$('capitalArt').classList.remove('gameArt');refreshMenuState()}
