function buildingCardHTML(type){let d=BLD[type],existing=S.buildings.find(b=>b.type===type),pending=existing&&S.queue.some(q=>q.kind==='upgrade'&&q.buildingId===existing.id),max=existing?.level>=d.max,prereq=prerequisite(type),slot=S.queue.length<queueSlots(),plot=!!freePlot(),can=canAfford(d.cost),lockedReason=!prereq?(d.requires==='keep2'?'نیازمند ارگ سطح ۲':`نیازمند ${BLD[d.requires]?.name||d.requires}`):!slot?'صف ساخت تکمیل است':!plot?'زمین خالی ندارید':!can?'منابع کافی نیست':'آماده ساخت';let cost=existing?Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,Math.floor(v*(existing.level+1)*.78)])):d.cost;let enabled=prereq&&slot&&(existing||plot)&&!max&&!pending&&canAfford(cost);if(pending)lockedReason='ارتقا در صف ساخت است';return `<div class="gameCard"><div class="cardTop"><div class="cardIcon">${svgIcon(d.icon)}</div><div class="cardTitle"><h3>${d.name}</h3><small>${d.type}${existing?` · سطح ${number(existing.level)}`:' · سازه تازه'}</small></div><span class="tag">${d.time||1} فصل</span></div><p class="cardDesc">${d.desc}</p><div class="cardMeta"><span class="tag">هزینه ${costText(cost)}</span>${d.rate?`<span class="tag">تولید: ${Object.entries(d.rate).map(([k,v])=>`${RES[k].name} +${number(v*(existing?.level||1))}`).join('، ')}</span>`:''}${d.defense?`<span class="tag">دفاع +${d.defense}</span>`:''}</div>${!enabled&&!max?`<div class="smallNote">${lockedReason}</div>`:''}<div class="cardActions"><button class="action" data-build="${type}" ${enabled?'':'disabled'}>${max?'حداکثر سطح':existing?'ارتقای بنا':'ساخت بنا'}</button></div></div>`}
function adjacentToPlayer(t){return WORLD.tiles.some(x=>x.owner==='player'&&hexDist(x,t)===1)}
function claimCostFor(t){let terrain=TERRAIN.find(x=>x.id===t.terrain);let mult=terrain.id==='mountain'?1.35:terrain.id==='desert'?1.2:1;let discount=S.research.includes('cartography')?.85:1;return {gold:Math.round(72*mult*discount),food:Math.round(34*mult*discount)}}
function tileDefense(t){let tr=TERRAIN.find(x=>x.id===t.terrain),wall=buildingLevel('wall')*4,tower=buildingLevel('watchtower')*3;return (tr?.def||1)+t.fort+ (t.owner==='player'?wall+tower:Math.round((S.factions.find(f=>f.id===t.owner)?.power||0)/24))}
function claimTile(id){let t=WORLD.tiles.find(x=>x.id===id);if(!t||t.owner||!TERRAIN.find(x=>x.id===t.terrain)?.pass||!adjacentToPlayer(t))return toast('این منطقه در حال حاضر قابل تصرف نیست.','bad');let cost=claimCostFor(t);if(!pay(cost))return toast('منابع کافی برای تصرف منطقه ندارید.','bad');t.owner='player';t.discovered=true;S.claimed.push(t.id);S.xp+=18;S.quests.claim++;for(const n of WORLD.tiles)if(hexDist(n,t)<=2)n.discovered=true;addLog(`منطقه ${TERRAIN.find(x=>x.id===t.terrain).name} به قلمرو امپراتوری پیوست.`);saveGame();updateHUD();renderPanel('world');drawWorld();AudioFX.play('claim')}
function explore(){let cost={gold:55,food:35};if(!pay(cost))return toast('برای اعزام نقشه‌نگاران منابع کافی نیست.','bad');let frontier=WORLD.tiles.filter(t=>t.owner==='player');let candidates=WORLD.tiles.filter(t=>!t.discovered&&frontier.some(p=>hexDist(p,t)<=3));if(!candidates.length)candidates=WORLD.tiles.filter(t=>!t.discovered&&hexDist(t,{q:9,r:7})<=6);candidates.sort((a,b)=>Math.min(...frontier.map(p=>hexDist(p,a)))-Math.min(...frontier.map(p=>hexDist(p,b))));let target=candidates[0];if(target){let radius=S.research.includes('cartography')?3:2;for(let t of WORLD.tiles)if(hexDist(t,target)<=radius)t.discovered=true;S.xp+=12;addLog('نقشه‌نگاران ناحیه‌ای تازه را روی نقشه ثبت کردند.');toast('بخشی از مه نقشه کنار رفت.','good')}else toast('همه سرزمین‌های نزدیک کشف شده‌اند.');saveGame();updateHUD();renderPanel('world');drawWorld()}
function startBuilding(type){let d=BLD[type],existing=S.buildings.find(b=>b.type===type),pending=existing&&S.queue.some(q=>q.kind==='upgrade'&&q.buildingId===existing.id),max=existing?.level>=d.max,prereq=prerequisite(type),plot=freePlot(),slot=S.queue.length<queueSlots(),cost=existing?Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,Math.floor(v*(existing.level+1)*.78)])):d.cost;if(max)return toast('این بنا به بالاترین سطح رسیده است.');if(pending)return toast('ارتقای این بنا از قبل در صف ساخت است.');if(!prereq)return toast('پیش‌نیاز ساخت فراهم نیست.','bad');if(!slot)return toast('تمام جایگاه‌های ساخت مشغول‌اند.','bad');if(!existing&&!plot)return toast('برای ساخت، یک منطقه آزاد در قلمرو تصرف کنید.','bad');if(!pay(cost))return toast('منابع کافی نیست.','bad');let time=Math.max(1,d.time||1)+(existing&&existing.level>=3?1:0);S.queue.push({id:Date.now()+Math.random(),type,kind:existing?'upgrade':'build',buildingId:existing?.id||null,tileId:existing?existing.tileId:plot.id,total:time,remaining:time});S.xp+=4;addLog(`${existing?'ارتقای':'ساخت'} ${d.name} آغاز شد؛ تکمیل در ${number(time)} فصل.`);saveGame();updateHUD();renderPanel('build');AudioFX.play('build')}
function recruitReason(id){let u=UNIT[id];if(armyCount()>=armyCapacity())return true;if(!canAfford(u.cost))return true;if(id==='swords'||id==='spears')return buildingLevel('barracks')<1;if(id==='archers')return buildingLevel('barracks')<2;if(id==='engineers')return buildingLevel('barracks')<3;if(id==='cavalry')return buildingLevel('stable')<1;if(id==='knights')return buildingLevel('stable')<2;return false}
function armyCapacity(){return 26+buildingLevel('keep')*7+buildingLevel('barracks')*12+buildingLevel('stable')*7}
function recruit(id,count=1){let u=UNIT[id];count=clamp(count,1,5);if(armyCount()+count>armyCapacity())return toast('ظرفیت سپاه تکمیل است.','bad');if(recruitReason(id))return toast('پیش‌نیاز یا منابع استخدام فراهم نیست.','bad');let cost=Object.fromEntries(Object.entries(u.cost).map(([k,v])=>[k,v*count]));if(!pay(cost))return toast('منابع کافی نیست.','bad');S.army[id]=(S.army[id]||0)+count;S.xp+=count*2;addLog(`${number(count)} ${u.name} به سپاه پیوستند.`);saveGame();updateHUD();renderPanel('army');AudioFX.play('recruit')}
function armyUpkeep(){let a={gold:0,food:0};for(let [id,n] of Object.entries(S.army)){let u=UNIT[id];a.gold+=u.upkeep*n;a.food+=u.food*n}let mult=S.research.includes('logistics')?.8:1;if(S.realm==='vale')mult*=.95;return {gold:Math.ceil(a.gold*mult),food:Math.ceil(a.food*mult)}}
